// Clean type aliases over the generated OpenAPI schema (src/generated/api.ts,
// regenerated by scripts/sync-types.sh — do not edit that file by hand).

import type { components } from "./generated/api.js";

type Schemas = components["schemas"];

export type SportEntry = Schemas["SportEntry"];
export type SportListResponse = Schemas["SportListResponse"];
export type StringListResponse = Schemas["StringListResponse"];

export type PlayerSummary = Schemas["PlayerSummary"];
